SELECT r.resume_sq AS freelancerSq, r.user_sq AS userSq, u.user_nm AS name, r.resume_ttl AS jobTitle, COALESCE(career.exp_years, 0) AS experienceYears, CONCAT('/api/v1/files/', p.file_sq) AS profileImageUrl, r.resume_greeting_txt AS summary, a.address AS address, a.detail_address AS detailAddress, a.sigungu AS sigungu FROM TBL_RESUME_M r
INNER JOIN ( SELECT user_sq, MAX(resume_sq) AS max_resume_sq FROM TBL_RESUME_M WHERE (resume_is_deleted_yn = 'N' OR resume_is_deleted_yn IS NULL) GROUP BY user_sq ) latest_r ON r.resume_sq = latest_r.max_resume_sq
INNER JOIN TBL_USER_M u ON r.user_sq = u.user_sq LEFT JOIN tbl_user_profile_image_s p ON u.user_sq = p.user_sq LEFT JOIN tbl_address_s a ON r.address_sq = a.address_sq
LEFT JOIN ( SELECT c.resume_sq, FLOOR(SUM(GREATEST(DATEDIFF(COALESCE(c.career_end_dt, CURDATE()), c.career_start_dt) + 1, 0)) / 365) AS exp_years FROM TBL_RESUME_CAREER_S c INNER JOIN ( SELECT user_sq, MAX(resume_sq) AS max_resume_sq FROM TBL_RESUME_M WHERE (resume_is_deleted_yn = 'N' OR resume_is_deleted_yn IS NULL) GROUP BY user_sq ) latest ON c.resume_sq = latest.max_resume_sq GROUP BY c.resume_sq ) career ON r.resume_sq = career.resume_sq
AND (u.user_is_deleted_yn = 'N' OR u.user_is_deleted_yn IS NULL) AND (r.resume_is_deleted_yn = 'N' OR r.resume_is_deleted_yn IS NULL) AND r.resume_ttl IS NOT NULL AND TRIM(r.resume_ttl) != ''
AND (
a.area_code_sq = 36110
(a.area_code_sq >= #{code} AND a.area_code_sq < #{code} + 1000)
a.area_code_sq = #{code}
)
AND ( CASE WHEN COALESCE(career.exp_years, 0) < 1 THEN 701 WHEN COALESCE(career.exp_years, 0) = 1 THEN 702 WHEN COALESCE(career.exp_years, 0) = 2 THEN 703 WHEN COALESCE(career.exp_years, 0) = 3 THEN 704 WHEN COALESCE(career.exp_years, 0) = 4 THEN 705 WHEN COALESCE(career.exp_years, 0) = 5 THEN 706 WHEN COALESCE(career.exp_years, 0) = 6 THEN 707 WHEN COALESCE(career.exp_years, 0) = 7 THEN 708 ELSE 709 END ) IN
#{item}
AND r.job_status_code_sq IN
#{item}
AND r.resume_sq IN ( SELECT rss.resume_sq FROM TBL_RESUME_SKILL_TAG_S rss WHERE ( rss.skill_tag_sq IN
#{item}
OR rss.parent_skill_tag_sq IN
#{item}
) )
AND (u.user_nm LIKE CONCAT('%', #{req.searchKeyword}, '%') OR r.resume_ttl LIKE CONCAT('%', #{req.searchKeyword}, '%'))
ORDER BY r.resume_sq DESC LIMIT #{req.size} OFFSET #{offset}

